mapper.sql:
WHERE 1 = 1
AND ( LOWER(L.MEMBER_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.LOGIN_ID) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.UNIV_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.MERCHANT_UID) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.PORTONE_PAYMENT_ID) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.PORTONE_SCHEDULE_ID) LIKE '%' || LOWER(#{keyword}) || '%' )
AND L.CATEGORY = #{category}
AND L.RESULT = #{result}
AND L.OCCURRED_AT >= CAST(SYSTIMESTAMP AS TIMESTAMP) - NUMTODSINTERVAL(#{periodDays}, 'DAY')

mapper.select:
SELECT * FROM ( SELECT L.* FROM (
) L
ORDER BY L.OCCURRED_AT DESC, L.CATEGORY ASC, L.SOURCE_ID DESC ) OFFSET #{offset} ROWS FETCH NEXT 12 ROWS ONLY

SELECT COUNT(*)
FROM (
    SELECT L.*
    FROM (

    ) L

)
